"""PEP 517 backend that builds and stages a private PLUMED runtime.

The kernel is built with configure/make on Linux and macOS, and with CMake
(CMakeLists.txt) on Windows.
"""

from __future__ import annotations

import contextlib
import hashlib
import os
from pathlib import Path
import platform
import re
import shlex
import shutil
import subprocess
import sys
import tempfile
import time

from setuptools import build_meta as _setuptools_backend


PYTHON_ROOT = Path(__file__).resolve().parent
RUNTIME_PACKAGE = PYTHON_ROOT / "plumed" / "runtime"
# directories of plumed/runtime generated by the build (and removed after it)
RUNTIME_DIRS = ("lib", "bin", "include", "share", "licenses")

# files and directories of the PLUMED source tree needed to build the kernel
BUILD_INPUT_FILES = (
    "CMakeLists.txt",
    "configure",
    "configure.ac",
    "Makefile",
    "Makefile.conf.in",
    "VERSION.txt",
    "COPYING.LESSER",
    "PEOPLE",
    "sourceme.sh.in",
    "stamp-h.in",
)
BUILD_INPUT_DIRS = (
    "src",
    "json",
    "scripts",
    "patches",
    "vim",
    "fortran",
    "cmake-msvc",
)
# build products that might be present in a developer tree
BUILD_PRODUCTS = ("*.o", "*.d", "*.on", "*.off")


def _verbose() -> bool:
    return os.environ.get("PLUMED_BUILD_VERBOSE", "").lower() in {"1", "yes", "true"}


def _show_failure(log: Path) -> None:
    """Print the relevant part of the log of a failed step."""
    lines = log.read_text(errors="replace").splitlines()
    error = re.compile(r"error[: ]|\*\*\*|Traceback|not found", re.IGNORECASE)
    errors = [line for line in lines if error.search(line)]
    if errors:
        print("PLUMED: lines that look like errors:", file=sys.stderr)
        for line in errors[:40]:
            print("  " + line, file=sys.stderr)
    print(f"PLUMED: last lines of {log}:", file=sys.stderr)
    for line in lines[-150:]:
        print("  " + line, file=sys.stderr)
    sys.stderr.flush()


@contextlib.contextmanager
def _captured_output(label: str):
    """Send the output of a build step to a log file and show it only on failure.

    The output of compilers and setuptools (thousands of lines, one for each
    file compiled, copied or added) makes CI logs hard to read. Set
    PLUMED_BUILD_VERBOSE=1 to see everything.
    """
    if _verbose():
        yield
        return
    handle, name = tempfile.mkstemp(prefix="plumed-build-", suffix=".log")
    log = Path(name)
    print(f"PLUMED: {label} (log in {log})", flush=True)
    sys.stderr.flush()
    saved = os.dup(1), os.dup(2)
    os.dup2(handle, 1)
    os.dup2(handle, 2)
    start = time.monotonic()
    succeeded = False
    try:
        yield
        succeeded = True
    finally:
        sys.stdout.flush()
        sys.stderr.flush()
        os.dup2(saved[0], 1)
        os.dup2(saved[1], 2)
        for fd in (*saved, handle):
            os.close(fd)
        if succeeded:
            print(
                f"PLUMED: {label}: done in {time.monotonic() - start:.0f} s", flush=True
            )
            log.unlink(missing_ok=True)
        else:
            print(f"PLUMED: {label}: FAILED", file=sys.stderr)
            _show_failure(log)


def _source_root() -> Path:
    staged = PYTHON_ROOT / "plumed_source"
    return staged if staged.is_dir() else PYTHON_ROOT.parent


def _copy_build_inputs(source: Path, destination: Path) -> None:
    destination.mkdir(parents=True)
    for filename in BUILD_INPUT_FILES:
        shutil.copy2(source / filename, destination / filename)
    for dirname in BUILD_INPUT_DIRS:
        shutil.copytree(
            source / dirname,
            destination / dirname,
            symlinks=True,
            ignore=shutil.ignore_patterns(*BUILD_PRODUCTS),
        )
    # the source distribution does not contain this link (see _copy_sdist_source);
    # the CMake build (Windows, where links may need privileges) does not use it
    include_link = destination / "src" / "include" / "plumed"
    if sys.platform == "win32":
        return
    if not include_link.is_symlink() and not include_link.exists():
        include_link.parent.mkdir(parents=True, exist_ok=True)
        include_link.symlink_to("../")


def _dependencies() -> Path | None:
    """Prefix of the libraries built by build_dependencies.py, if any.

    Set PLUMED_DEPENDENCIES to it to link the kernel to zlib, HDF5 and
    chemfiles statically, as in the wheels (see pyproject.toml).
    """
    setting = os.environ.get("PLUMED_DEPENDENCIES")
    if not setting:
        return None
    prefix = Path(setting).resolve()
    if not (prefix / "plumed-dependencies.txt").is_file():
        raise RuntimeError(
            f"PLUMED_DEPENDENCIES={setting}: build the libraries first, with "
            "python build_dependencies.py " + setting
        )
    return prefix


def _runtime_cache_key(source: Path, modules: list[str]) -> str:
    """Identify a runtime build: sources, build recipe, platform and compiler settings.

    The kernel does not depend on the Python version, so cibuildwheel can build it
    once and reuse it for all the Python versions (see PLUMED_RUNTIME_CACHE).
    """
    digest = hashlib.sha256()
    settings = [sys.platform, platform.machine(), " ".join(modules)]
    for name in (
        "MACOSX_DEPLOYMENT_TARGET",
        "CC",
        "CXX",
        "CFLAGS",
        "CXXFLAGS",
        "LDFLAGS",
    ):
        settings.append(f"{name}={os.environ.get(name, '')}")
    dependencies = _dependencies()
    if dependencies:
        settings.append((dependencies / "plumed-dependencies.txt").read_text())
    for item in settings:
        digest.update(item.encode() + b"\0")
    digest.update(Path(__file__).read_bytes())
    paths = [source / name for name in BUILD_INPUT_FILES]
    for dirname in BUILD_INPUT_DIRS:
        paths.extend(
            path
            for path in (source / dirname).rglob("*")
            if not any(path.match(pattern) for pattern in BUILD_PRODUCTS)
        )
    for path in sorted(paths):
        digest.update(str(path.relative_to(source)).encode() + b"\0")
        if path.is_symlink():
            digest.update(os.readlink(path).encode() + b"\0")
        elif path.is_file():
            digest.update(path.read_bytes())
    return digest.hexdigest()[:24]


def _restore_runtime(cached: Path) -> None:
    for name in RUNTIME_DIRS:
        shutil.rmtree(RUNTIME_PACKAGE / name, ignore_errors=True)
        if (cached / name).is_dir():
            shutil.copytree(cached / name, RUNTIME_PACKAGE / name, symlinks=True)


def _store_runtime(cached: Path) -> None:
    staging = cached.with_name(cached.name + f".tmp{os.getpid()}")
    shutil.rmtree(staging, ignore_errors=True)
    staging.mkdir(parents=True)
    for name in RUNTIME_DIRS:
        if (RUNTIME_PACKAGE / name).is_dir():
            shutil.copytree(RUNTIME_PACKAGE / name, staging / name, symlinks=True)
    (staging / ".complete").touch()
    try:
        staging.rename(cached)
    except OSError:
        # another build stored it in the meantime
        shutil.rmtree(staging, ignore_errors=True)


def _default_modules(source: Path) -> list[str]:
    modules = []
    for module_type in sorted((source / "src").glob("*/module.type")):
        kind = module_type.read_text().strip()
        if kind in {"always", "default-on"}:
            modules.append(module_type.parent.name)
    return modules


def _run(command: list[str], *, cwd: Path, env: dict[str, str] | None = None) -> None:
    print("+", " ".join(command), flush=True)
    subprocess.run(command, cwd=cwd, env=env, check=True)


def _bundle_kernel_enabled() -> bool:
    setting = os.environ.get("PLUMED_BUILD_KERNEL")
    if setting is None and os.environ.get("plumed_default_kernel"):
        return False
    return (setting or "1").lower() not in {"0", "no", "false"}


def _plumed_version(source: Path) -> str:
    # VERSION.txt starts with comment lines
    for line in (source / "VERSION.txt").read_text().splitlines():
        line = line.strip()
        if line and not line.startswith("#"):
            return line
    return "unknown"


def _install_runtime(source: Path, modules: list[str], env: dict[str, str]) -> None:
    # Stage the complete standard installation. DESTDIR keeps the configured
    # prefix stable while ensuring make never writes outside the build tree.
    destination = source.parent / "install"
    _run(["make", "install", f"DESTDIR={destination}"], cwd=source, env=env)
    installed = destination / "plumed_runtime"
    _stage_runtime(installed)
    runtime_lib = RUNTIME_PACKAGE / "lib"
    runtime_bin = RUNTIME_PACKAGE / "bin"

    # Loader repair and plugin linking are wheel-specific; file selection and
    # installation layout belong entirely to make install.
    _relocate_compile_options(
        runtime_lib / "plumed" / "src" / "config" / "compile_options.sh"
    )
    _drop_dependency_paths(
        [
            runtime_lib / "plumed" / "src" / "config" / "compile_options.sh",
            runtime_lib / "plumed" / "src" / "config" / "config.txt",
            *sorted((runtime_lib / "pkgconfig").glob("*.pc")),
        ]
    )
    _finish_runtime(source, modules, "configure/make")

    if sys.platform == "darwin":
        _fix_macos_load_paths(runtime_lib, runtime_bin)
    else:
        _check_linux_run_paths(runtime_lib, runtime_bin)


def _stage_runtime(installed: Path) -> None:
    """Copy an installation prefix to plumed/runtime."""
    for name in RUNTIME_DIRS:
        shutil.rmtree(RUNTIME_PACKAGE / name, ignore_errors=True)
    shutil.copytree(installed, RUNTIME_PACKAGE, dirs_exist_ok=True, symlinks=True)


def _finish_runtime(source: Path, modules: list[str], build_system: str) -> None:
    """Licenses and build information, common to all the build systems."""
    runtime_root = RUNTIME_PACKAGE / "lib" / "plumed"
    license_dir = RUNTIME_PACKAGE / "licenses"
    license_dir.mkdir(parents=True, exist_ok=True)
    shutil.copy2(source / "COPYING.LESSER", license_dir / "COPYING.LESSER")
    dependencies = _dependencies()
    if dependencies:
        # the licenses of the libraries linked statically in the kernel
        shutil.copytree(dependencies / "licenses", license_dir, dirs_exist_ok=True)
        libraries = ", ".join(
            (dependencies / "plumed-dependencies.txt").read_text().splitlines()
        )
    else:
        libraries = "none"
    build_info = [
        f"PLUMED version: {_plumed_version(source)}",
        f"Build system: {build_system}",
        "Shared kernel: enabled",
        "MPI: disabled",
        "OpenMP: disabled",
        "External BLAS/LAPACK: disabled",
        "External FFTW: disabled",
        f"Libraries linked statically: {libraries}",
        "Enabled modules: " + ", ".join(modules),
    ]
    (runtime_root / "build-info.txt").write_text("\n".join(build_info) + "\n")

    # setuptools follows symbolic links when packing the wheel
    links = [path for path in RUNTIME_PACKAGE.rglob("*") if path.is_symlink()]
    if links:
        raise RuntimeError(f"unexpected symbolic links in the runtime: {links[:5]}")


def _drop_dependency_paths(paths: list[Path]) -> None:
    """Remove the static libraries of PLUMED_DEPENDENCIES from the link commands.

    They are in the kernel already, and their build paths do not exist where
    the wheel is installed (plumed mklib and LOAD would fail).
    """
    dependencies = _dependencies()
    if dependencies is None:
        return
    for path in paths:
        if not path.is_file():
            continue
        lines = []
        for line in path.read_text().splitlines():
            words = []
            for word in line.split(" "):
                if str(dependencies) in word:
                    # also as the first value of a variable (CPPFLAGS=-I...)
                    key, equal, _ = word.partition("=")
                    if not equal or str(dependencies) in key:
                        continue
                    word = key + equal
                words.append(word)
            lines.append(" ".join(words))
        path.write_text("\n".join(lines) + "\n")


def _relocate_compile_options(path: Path) -> None:
    """Make compile_options.sh (used by plumed mklib and LOAD) work in the wheel.

    - The kernel is linked from the installed wheel instead of the build tree
      (mklib evaluates the commands with PLUMED_ROOT set to lib/plumed).
      Remove build-tree link commands, as make install does.
    - The plugin records an rpath to the kernel, and on Linux the kernel is
      linked with --no-as-needed: toolchains defaulting to --as-needed (e.g.
      Ubuntu) must retain it as a dependency even for plugins using no symbols.
      From Python the kernel is loaded with RTLD_LOCAL, so a plugin that does
      not list it as a dependency cannot resolve PLUMED symbols.
    - manylinux compilers use the old libstdc++ string ABI, which plugins
      compiled with a newer compiler must use as well.
    """
    kernel_dir = '"$PLUMED_ROOT"/..'
    link_flags = f"-Wl,-rpath,{kernel_dir}"
    if sys.platform.startswith("linux"):
        link_flags = "-Wl,--no-as-needed " + link_flags
    lines = []
    for line in path.read_text().splitlines():
        if line.startswith(("link_uninstalled=", "link_libs_uninstalled=")):
            continue
        # Rewrite installed linking commands (link_shared has no kernel).
        if line.startswith("link_") and "libplumedKernel." in line:
            line, count = re.subn(
                r"\S*/(libplumedKernel\.(?:so|dylib))",
                lambda match: f"{link_flags} {kernel_dir}/{match.group(1)}",
                line,
            )
            if count != 1:
                raise RuntimeError(f"cannot relocate the kernel in {line}")
        elif line.startswith("compile='") and _uses_old_cxx_abi(line):
            line = line.rstrip()[:-1].rstrip() + " -D_GLIBCXX_USE_CXX11_ABI=0'"
        lines.append(line)
    path.write_text("\n".join(lines) + "\n")


def _uses_old_cxx_abi(compile_line: str) -> bool:
    if not sys.platform.startswith("linux"):
        return False
    compiler = shlex.split(compile_line[len("compile='") :].split(" -c ")[0])
    probe = subprocess.run(
        [*compiler, "-x", "c++", "-E", "-"],
        input="#include <string>\n_GLIBCXX_USE_CXX11_ABI\n",
        capture_output=True,
        text=True,
    )
    lines = [line.strip() for line in probe.stdout.splitlines() if line.strip()]
    return probe.returncode == 0 and bool(lines) and lines[-1] == "0"


def _check_linux_run_paths(runtime_lib: Path, runtime_bin: Path) -> None:
    # libplumed and the executable need libplumedKernel: without a relative run
    # path neither the loader nor auditwheel can find it inside the wheel.
    for binary in (runtime_lib / "libplumed.so", runtime_bin / "plumed"):
        dynamic = subprocess.check_output(["readelf", "-d", str(binary)], text=True)
        if "$ORIGIN/../lib" not in dynamic:
            raise RuntimeError(
                f"{binary.name} was linked without the $ORIGIN/../lib run path:\n"
                + dynamic
            )


def _fix_macos_load_paths(runtime_lib: Path, runtime_bin: Path) -> None:
    kernel = runtime_lib / "libplumedKernel.dylib"
    wrapper = runtime_lib / "libplumed.dylib"
    executable = runtime_bin / "plumed"
    _run(
        ["install_name_tool", "-id", "@rpath/libplumedKernel.dylib", str(kernel)],
        cwd=runtime_lib,
    )
    _run(
        ["install_name_tool", "-id", "@rpath/libplumed.dylib", str(wrapper)],
        cwd=runtime_lib,
    )
    for binary in (wrapper, executable):
        dependencies = subprocess.check_output(["otool", "-L", str(binary)], text=True)
        for line in dependencies.splitlines()[1:]:
            dependency = line.strip().split(" ", 1)[0]
            if dependency.endswith("/libplumedKernel.dylib"):
                _run(
                    [
                        "install_name_tool",
                        "-change",
                        dependency,
                        "@rpath/libplumedKernel.dylib",
                        str(binary),
                    ],
                    cwd=runtime_lib,
                )
            elif dependency.endswith("/libplumed.dylib"):
                _run(
                    [
                        "install_name_tool",
                        "-change",
                        dependency,
                        "@rpath/libplumed.dylib",
                        str(binary),
                    ],
                    cwd=runtime_lib,
                )
        _run(
            [
                "install_name_tool",
                "-add_rpath",
                "@loader_path/../lib" if binary == executable else "@loader_path",
                str(binary),
            ],
            cwd=runtime_lib,
        )


def _build_runtime() -> None:
    if sys.platform not in {"linux", "darwin", "win32"}:
        raise RuntimeError(
            "Bundled PLUMED kernels are supported on Linux, macOS and Windows only"
        )
    source_root = _source_root()
    modules = _default_modules(source_root)
    if not modules:
        raise RuntimeError("No always or default-on PLUMED modules were found")

    cache_root = os.environ.get("PLUMED_RUNTIME_CACHE")
    cached = None
    if cache_root:
        cached = Path(cache_root) / _runtime_cache_key(source_root, modules)
        if (cached / ".complete").is_file():
            print(f"PLUMED: reusing the kernel built in {cached}", flush=True)
            _restore_runtime(cached)
            return

    with _captured_output("building the PLUMED kernel"):
        if sys.platform == "win32":
            _compile_runtime_cmake(source_root, modules)
        else:
            _compile_runtime(source_root, modules)
    if cached:
        _store_runtime(cached)


def _compile_runtime(source_root: Path, modules: list[str]) -> None:
    with tempfile.TemporaryDirectory(prefix="plumed-wheel-build-") as temporary:
        source = Path(temporary) / "plumed"
        _copy_build_inputs(source_root, source)
        prefix = "/plumed_runtime"
        module_option = "--enable-modules=none:" + ":".join(
            "+" + name for name in modules
        )
        configure = [
            "./configure",
            f"--prefix={prefix}",
            f"BASH_COMPLETION_DIR={prefix}/share/bash-completion/completions",
            module_option,
            "--enable-shared",
            "--disable-static-archive",
            "--disable-static-patch",
            "--disable-python",
            "--disable-doc",
            "--disable-mpi",
            "--disable-openmp",
            "--disable-external-blas",
            "--disable-external-lapack",
            "--disable-fftw",
            "--disable-zlib",
            "--disable-rpath",
            "CXXFLAGS="
            + (os.environ.get("CXXFLAGS", "") + " -O2 -D__PLUMED_PIP_BUNDLE").strip(),
            "CFLAGS=" + (os.environ.get("CFLAGS", "") + " -O2").strip(),
        ]
        if sys.platform == "darwin":
            configure.append("--disable-absolute-install-name")
        configure += _configure_dependencies()
        try:
            _run(configure, cwd=source)
        except subprocess.CalledProcessError:
            # config.log is in the temporary tree: show it before it is removed
            config_log = source / "config.log"
            if config_log.is_file():
                print("+ tail of config.log")
                lines = config_log.read_text(errors="replace").splitlines()
                print("\n".join(lines[-80:]), flush=True)
            raise
        jobs = str(max(1, min(4, os.cpu_count() or 1)))
        # The runtime executable is installed under bin/ and its bundled libraries
        # under lib/. A relative run path lets auditwheel resolve the kernel inside
        # the wheel, and remains valid after installation at any prefix.
        link_env = os.environ.copy()
        link_env["LD_RUN_PATH"] = "$ORIGIN/../lib"
        _run(["make", "-C", "src/config"], cwd=source, env=link_env)
        _run(["make", "-C", "src/lib", "-j" + jobs], cwd=source, env=link_env)

        _install_runtime(source, modules, link_env)


def _configure_dependencies() -> list[str]:
    """configure options for the libraries of build_dependencies.py."""
    dependencies = _dependencies()
    if dependencies is None:
        return []
    lib = dependencies / "lib"
    # full paths: the static libraries, not shared ones elsewhere in the paths
    libs = [str(lib / name) for name in ("libchemfiles.a", "libhdf5.a", "libz.a")]
    ldflags = os.environ.get("LDFLAGS", "")
    # the kernel does not export their symbols, so that it can be loaded with
    # other copies of these libraries (e.g. the HDF5 of h5py or of an MD code)
    if sys.platform.startswith("linux"):
        libs += ["-ldl", "-lm"]
        ldflags += " -Wl,--exclude-libs,ALL"
    elif sys.platform == "darwin":
        libs = [f"-Wl,-load_hidden,{library}" for library in libs]
    return [
        "--enable-libhdf5",
        "--enable-libchemfiles",
        "CPPFLAGS="
        + (os.environ.get("CPPFLAGS", "") + f" -I{dependencies / 'include'}").strip(),
        "LDFLAGS=" + ldflags.strip(),
        "LIBS=" + " ".join(libs),
    ]


def _compile_runtime_cmake(source_root: Path, modules: list[str]) -> None:
    """Build the kernel with CMake (Windows, MSVC).

    Without CMAKE_GENERATOR, CMake uses the newest Visual Studio, which needs no
    developer command prompt. The C and C++ runtime is linked statically (/MT),
    so that the kernel and plumed.exe do not depend on the Visual C++
    redistributable (msvcp140.dll), whose version in the process is decided by
    whoever loads it first. The kernel exposes a C interface only, so no C
    runtime object crosses the boundary with the python module.
    """
    cmake = shutil.which("cmake")
    if cmake is None:
        raise RuntimeError("cmake is needed to build the PLUMED kernel on Windows")
    # MSBuild processes left running might still hold files of the build
    with tempfile.TemporaryDirectory(
        prefix="plumed-wheel-build-", ignore_cleanup_errors=True
    ) as temporary:
        source = Path(temporary) / "plumed"
        build = Path(temporary) / "build"
        installed = Path(temporary) / "install"
        _copy_build_inputs(source_root, source)
        jobs = str(max(1, min(4, os.cpu_count() or 1)))
        _run(
            [
                cmake,
                "-S",
                str(source),
                "-B",
                str(build),
                "-DCMAKE_BUILD_TYPE=Release",
                "-DPLUMED_SHARED_KERNEL=ON",
                "-DPLUMED_PIP_BUNDLE=ON",
                "-DCMAKE_MSVC_RUNTIME_LIBRARY=MultiThreaded",
                # the path compiled in the kernel, which finds its resources
                # relative to itself (as /plumed_runtime with configure)
                "-DCMAKE_INSTALL_PREFIX=C:/plumed_runtime",
                *_cmake_dependencies(),
            ],
            cwd=Path(temporary),
        )
        _run(
            [cmake, "--build", str(build), "--config", "Release", "--parallel", jobs],
            cwd=Path(temporary),
        )
        _run(
            [
                cmake,
                "--install",
                str(build),
                "--config",
                "Release",
                "--prefix",
                str(installed),
            ],
            cwd=Path(temporary),
        )
        _stage_runtime(installed)
        _finish_runtime(source, modules, "CMake")


def _cmake_dependencies() -> list[str]:
    """CMake options for the libraries of build_dependencies.py."""
    dependencies = _dependencies()
    if dependencies is None:
        return []
    return [
        "-DPLUMED_ENABLE_HDF5=ON",
        "-DPLUMED_ENABLE_CHEMFILES=ON",
        f"-DCMAKE_PREFIX_PATH={dependencies.as_posix()}",
    ]


def _copy_sdist_source(destination: Path) -> None:
    _copy_build_inputs(PYTHON_ROOT.parent, destination)
    # src/include/plumed is a link to ../: setuptools would follow it recursively
    # (a 120 MB sdist, with tens of thousands of copies of the sources).
    # _copy_build_inputs creates it again when the kernel is built.
    (destination / "src" / "include" / "plumed").unlink()


def build_sdist(sdist_directory, config_settings=None):
    staged = PYTHON_ROOT / "plumed_source"
    created = not staged.exists()
    try:
        if created:
            _copy_sdist_source(staged)
        os.environ["plumed_force_cython"] = "yes"
        with _captured_output("building the source distribution"):
            return _setuptools_backend.build_sdist(sdist_directory, config_settings)
    finally:
        if created:
            shutil.rmtree(staged, ignore_errors=True)


def build_wheel(wheel_directory, config_settings=None, metadata_directory=None):
    kernel_setting = os.environ.get("PLUMED_BUILD_KERNEL")
    force_cython_setting = os.environ.get("plumed_force_cython")
    # PLUMED's in-tree install passes plumed_default_kernel when building the
    # traditional wrapper-only interface from a staged python/ directory.
    bundle_kernel = _bundle_kernel_enabled()
    if kernel_setting is None and not bundle_kernel:
        os.environ["PLUMED_BUILD_KERNEL"] = "0"
    if bundle_kernel and force_cython_setting is None:
        os.environ["plumed_force_cython"] = "yes"
    try:
        if bundle_kernel:
            _build_runtime()
        with _captured_output("building the Python module and the wheel"):
            return _setuptools_backend.build_wheel(
                wheel_directory, config_settings, metadata_directory
            )
    finally:
        if kernel_setting is None:
            os.environ.pop("PLUMED_BUILD_KERNEL", None)
        if force_cython_setting is None:
            os.environ.pop("plumed_force_cython", None)
        for name in RUNTIME_DIRS:
            path = RUNTIME_PACKAGE / name
            if path.is_dir():
                shutil.rmtree(path, ignore_errors=True)
            elif path.exists():
                path.unlink()


